"""Render separate, offline coverage and NTA reports from audited evidence."""
import datetime as dt,html,json
from pathlib import Path

def shell(title,body):
 return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+html.escape(title)+'''</title><style>body{font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#ddd);margin:0}h1{font-size:23px;line-height:1.3}h2{font-size:18px;margin-top:25px}p{max-width:85ch}.note,figcaption{font-size:12px;color:var(--muted-foreground,#999)}figure{margin:16px 0;overflow-x:auto}svg{width:100%;min-width:660px;display:block}svg text{fill:currentColor;font:12px var(--font-sans,system-ui)}table{width:100%;min-width:640px;border-collapse:collapse;font-size:12px}td,th{padding:6px;text-align:left;border-bottom:1px solid var(--border,#555)}.scroll{overflow:auto;max-height:480px}.scroll th{position:sticky;top:0;background:var(--card,#222)}.callout{border-left:3px solid var(--chart-2,#ba8);padding-left:12px}input{font:inherit;padding:8px;border:1px solid var(--border,#666);border-radius:5px;background:var(--secondary,#222);color:inherit;max-width:90%}details{margin:14px 0}code{overflow-wrap:anywhere}li{margin:6px 0}</style></head><body>'''+body+'</body></html>'

def barplot(items,maximum,label):
 H=45+len(items)*44;svg=f'<svg viewBox="0 0 700 {H}" role="img" aria-label="{html.escape(label)}">'
 for i,(name,value,total) in enumerate(items):
  y=10+i*44;svg+=f'<text x="0" y="{y+14}">{html.escape(name)}</text><rect x="260" y="{y}" width="{value/maximum*350}" height="20" fill="var(--chart-1,#5a9)"/><text x="{270+value/maximum*350}" y="{y+14}">{value}/{total}</text>'
 svg+=f'<text x="260" y="{H-5}">{html.escape(label)} · scale 0–{maximum}</text></svg>';return svg

def render(directory):
 c=json.loads((directory/'coverage.json').read_text());n=json.loads((directory/'nta-comparison.json').read_text());core=c['summary']['departures_in_window'];boundary=c['summary']['underway_at_start'];esc=html.escape
 body='''<h1>Every scheduled departure is represented. Stop histories still have gaps.</h1><p class="note">AWS DART trial · 21 Nov 2026 21:27 to 22 Nov 2026 21:27 Dublin time (UTC), with final movement checks until 23:27. Evidence: archived GTFS versions and original Irish Rail response bodies.</p>'''
 body+=f'<p><b>{core["statuses"].get("strict_match",0)} of {core["scheduled"]} scheduled corridor departures matched</b> by train code, service date, exact origin departure time and passenger-stop order. Both archived timetable versions agree on this cohort; no version conflict was found.</p>'
 body+='<figure>'+barplot([('Departures inside trial',core['statuses'].get('strict_match',0),core['scheduled']),('Scheduled underway at start',boundary['statuses'].get('strict_match',0),boundary['scheduled'])],100,'Matched journeys (count)')+'<figcaption>Each scheduled journey is counted once, not once per poll or stop. The ten underway-at-start journeys are a separate boundary cohort.</figcaption></figure>'
 body+='<h2>What we can claim</h2><p class="callout">All 89 corridor DART journeys listed in the archived GTFS timetables with a scheduled departure inside this trial window were captured in Irish Rail records, with reported origin-departure evidence. All ten scheduled journeys already underway at the window start also matched.</p><p>This does not prove that every planned stop was served, that every recorded time is physically accurate, or that every journey has a complete event history. It does not establish coverage for the separate 17–18 November local trial.</p>'
 body+='<h2>Journeys versus complete stop histories</h2><ul>'
 body+=f'<li>{core["seen_running"]}/{core["scheduled"]} departing journeys appeared in running-position reports. E137 on 22 November was absent from running-position snapshots but has reported origin departure and destination arrival.</li>'
 body+=f'<li>{core["origin_departures"]}/{core["scheduled"]} have an origin-departure value; {core["destination_arrivals"]}/{core["scheduled"]} have a non-empty destination-arrival field in the original trial.</li>'
 body+=f'<li>There are {core["arrivals_available"]:,}/{core["arrivals_required"]:,} non-empty required arrival fields and {core["departures_available"]:,}/{core["departures_required"]:,} departure fields. Nine of each are missing, all on E907.</li>'
 body+=f'<li>Two arrival values and one departure value equal 00:00:00 with automatic-generation flags. They remain in the raw data and are flagged for midnight/sentinel review; field presence does not establish timestamp validity.</li></ul>'
 body+='<h2>The incomplete case: E907, 22 November</h2><p>Greystones to Howth. The original archive has a Connolly arrival of 13:29:06, but no subsequent actual arrivals at Clontarf Road, Killester, Harmonstown, Raheny, Kilbarrack, Howth Junction, Bayside, Sutton or Howth. Its missing departures start at Connolly.</p><p>A post-trial query on 23 November reports a Howth arrival of 14:00 with AutoArrival=0. This was still empty at the final archived request at 16:03 on 22 November. The later response is saved separately and is <b>not counted</b> as original-trial coverage. Intermediate gaps remain unresolved.</p><p class="callout">Collection improvement: retain continuous raw sampling, then recheck known services the following day for settled final events. Keep original and backfilled versions, fetch times and flags separate.</p>'
 body+='<h2>How the proof works</h2><ol><li>Use only timetable versions actually archived during this run. Apply operating calendars and date exceptions, including GTFS times beyond 24:00.</li><li>Enumerate explicit DART routes whose passenger stops stay within the 32-station corridor. Select departures inside the exact trial interval; report overlapping journeys separately.</li><li>Find the corresponding Irish Rail identity and require an exact origin scheduled time and full ordered passenger-stop pattern. Operational timing points do not replace passenger-stop rows with the same code.</li><li>Require operating evidence, not just a future station-board listing. Here all 89 have reported origin departures.</li><li>List every unmatched or conflicting identity and every missing event. There are zero unmatched departing journeys and no timetable-version conflicts in this run.</li></ol>'
 body+=f'<p class="note">All {c["raw_bodies_verified"]:,} original Irish Rail bodies were decompressed and matched their saved SHA-256 hashes. The two GTFS versions each contain 99 overlapping journeys: 89 starting within the window and ten starting earlier. Five additional observed services are outside this planned-overlap cohort: E927, E828, E240 and E113 on 21 November, and E921 on 22 November. Their inclusion in the raw archive is not evidence of a missing scheduled journey.</p>'
 body+='<h2>Journey-level evidence ledger</h2><label>Filter by train code or service date <input id="search" placeholder="For example E907 or 2026-11-22"></label><div class="scroll"><table><thead><tr><th>Code / service date</th><th>Scheduled origin</th><th>Cohort</th><th>Exact match</th><th>Departure field</th><th>Destination field</th><th>Arrivals filled</th></tr></thead><tbody id="ledger"></tbody></table></div>'
 data=[{k:t[k] for k in ['code','service_date','start','cohort','status','origin_departure_available','destination_arrival_available','arrivals_available','arrivals_required','match_evidence']} for t in c['journeys']]
 body+='''<script>const rows='''+json.dumps(data)+''';const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');function show(){const query=document.querySelector('#search').value.toLowerCase();document.querySelector('#ledger').innerHTML=rows.filter(t=>(t.code+' '+t.service_date).toLowerCase().includes(query)).map(t=>`<tr><td>${esc(t.code)} / ${t.service_date}</td><td>${new Date(t.start*1000).toISOString().slice(11,16)}</td><td>${t.cohort==='departures_in_window'?'Departure in window':'Underway at start'}</td><td>${t.status==='strict_match'?'Yes':t.status}</td><td>${t.origin_departure_available?'Present':'Missing'}</td><td>${t.destination_arrival_available?'Present':'Missing'}</td><td>${t.arrivals_available}/${t.arrivals_required}</td></tr>`).join('');}document.querySelector('#search').oninput=show;show();</script>'''
 body+='<p class="note">Full stop-level records, original S3 response keys, timetable index keys and exceptions are in coverage.json. Rebuild with scripts/audit_coverage.py and scripts/render_coverage.py. NTA is assessed separately in nta-comparison.html.</p>'
 (directory/'coverage.html').write_text(shell('DART timetable coverage audit',body))
 pred=n['future_prediction_comparison'];pairs=n['prediction_pairs']
 body='<h1>NTA contains DART updates, but adds little coverage in this trial</h1><p class="note">Separate NTA assessment · same 21–22 November AWS trial · GTFS-matched DART entities only. Bus and other-operator records are excluded from these figures.</p>'
 body+=f'<p>The {n["snapshots"]} archived snapshots contain {n["entity_kinds"].get("trip_update",0):,} repeated DART trip-update records. All {n["scheduled_core_journeys"]} scheduled departures in the core cohort appear in NTA, and all were already captured independently in our Irish Rail archive. No additional missing core journey was recovered.</p>'
 body+='<figure>'+barplot([('Irish Rail: matched schedules',core['statuses'].get('strict_match',0),core['scheduled']),('NTA: identities appearing',n['scheduled_core_seen_in_nta'],n['scheduled_core_journeys'])],100,'Core scheduled journeys (count)')+'<figcaption>The Irish Rail match checks stopping pattern and origin schedule. The NTA count checks the exact archived GTFS trip identity and service date. Neither counts repeated polls as extra journeys.</figcaption></figure>'
 body+=f'<h2>What NTA actually supplied</h2><ul><li>Timetable-linked trip identities, service dates, per-stop delays and update timestamps.</li><li>All {n["delay_values"]:,} supplied delay values are whole-minute multiples. Irish Rail movement records preserve seconds.</li><li>All {sum(n["schedule_relationships"].values()):,} DART records use the SCHEDULED relationship. This run contains no explicit cancelled or added DART trip state; it cannot establish what the API might report in another disruption.</li><li>No vehicle-position entries in these DART snapshots. A separate live Vehicles-endpoint probe also returned no identified DART vehicles.</li></ul>'
 body+='<h2>How different were the predictions?</h2>'
 body+=f'<p>For {pairs:,} paired future-event predictions with matching scheduled clocks and source/fetch skew ≤30 seconds, the median absolute difference was {pred["median_absolute_difference_seconds"]:.0f} seconds; the 95th percentile was {pred["p95_absolute_difference_seconds"]:.0f} seconds.</p>'
 items=[('Difference ≤30 seconds',pred['within_30_seconds'],pairs),('Difference 31–60 seconds',pred['within_60_seconds']-pred['within_30_seconds'],pairs),('Difference >60 seconds',pairs-pred['within_60_seconds'],pairs)]
 body+='<figure>'+barplot(items,15000,'Paired forecast events (count)')+'<figcaption>Source: same-poll NTA trip updates versus Irish Rail expected times. This compares content, not independent accuracy. Repeated predictions are correlated. Pairs with mismatching static scheduled clocks were excluded.</figcaption></figure>'
 body+='<h2>Recommendation</h2><p class="callout">Keep versioned GTFS timetables and Irish Rail as the primary DART sources. Retain this NTA archive for reproducibility. There is no demonstrated DART GPS or journey-coverage gain here; a separate bus project is a different use case.</p><p>NTA can still be useful for timetable-native passenger predictions and cross-mode connection studies. The observed differences do not prove one source is more accurate, or that the two sources are independent.</p><p class="note">Full counts, pairing exclusions and examples are in nta-comparison.json. Rebuild with scripts/compare_nta_dart.py. The coverage claim belongs in coverage.html and is based on the original Irish Rail trial evidence, not later backfill.</p>'
 (directory/'nta-comparison.html').write_text(shell('NTA DART comparison',body))
 print('Wrote separate coverage.html and nta-comparison.html')
if __name__=='__main__':render(Path('data/coverage-audit'))
